fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Requires: n must be greater than 0, x must be non-negative, and a and b must be within bounds
    // Ensures: The result is the maximum possible distance between a and b after up to x moves, 
    //          constrained by the maximum distance of n - 1.
    // Invariant: The initial distance is always non-negative and the result is always within bounds.
    // Decreases: The distance calculation does not decrease, but we ensure the result is bounded.
    // Supporting assertions: The initial distance and max distance calculations are valid.

    // Requires: n > 0 && 0 <= x && -1 < a < n && -1 < b < n
    assert!(n > 0);
    assert!(x >= 0);
    assert!(a > -1 && a < n);
    assert!(b > -1 && b < n);

    // Calculate the initial distance between positions a and b
    let initial_distance = (a - b).abs();

    // Calculate the maximum possible distance after performing up to x moves
    let max_distance = initial_distance + x;

    // The maximum distance cannot exceed n - 1
    let result = max_distance.min(n - 1);

    // Ensures: result is in the range [0, n - 1]
    assert!(result >= 0 && result <= n - 1);

    result
}

